class Solution:
    def searchRange(self, nums: List[int], target: int) -> List[int]:
        leftmost = bisect_left(nums, target)
        if leftmost == len(nums) or nums[leftmost] != target:
            return [-1, -1]
        rightmost = bisect_left(nums, target + 1) - 1
        return [leftmost, rightmost]
